            del self._store[k]

    @property
    def size(self) -> int:
        return len(self._store)

    def stats(self) -> Dict[str, int]:
        now = time.time()
        active: int = sum(1 for _, (_, exp) in self._store.items() if now <= exp)
        return {
            "total_entries": len(self._store),
            "active": active,
            "expired": len(self._store) - active,
