"""Simple TTL cache for expensive lookups."""

import time
from typing import Any, Callable, Dict, List, Optional, Tuple, TypeVar

T = TypeVar("T")


class TTLCache:
    def __init__(self, ttl_seconds: int = 300, max_size: int = 1000) -> None:
